package com.mycompany.rentalmanagement.servlet;import com.mycompany.rentalmanagement.dao.PaymentDAO;import com.mycompany.rentalmanagement.util.ValidationUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/payments") public class PaymentServlet extends HttpServlet{PaymentDAO dao=new PaymentDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("payments",dao.list());r.setAttribute("payableRentals",dao.payableRentals());r.getRequestDispatcher("/WEB-INF/views/payments.jsp").forward(r,s);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/views/error.jsp").forward(r,s);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String method=r.getParameter("payment_method");if(!java.util.Set.of("CASH","CARD","UPI","BANK_TRANSFER","OTHER").contains(method))throw new IllegalArgumentException("Select a valid payment method.");dao.record(Long.parseLong(r.getParameter("rental_id")),ValidationUtil.money(r.getParameter("amount"),"Amount"),method,r.getParameter("reference_number"),r.getParameter("notes"));s.sendRedirect(r.getContextPath()+"/payments?success=1");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}}
